SELECT user_id, resource_type, resource_id, created_at, updated_at
FROM health_resource_favorite
WHERE user_id = #{userId}

    AND resource_type = #{resourceType}

ORDER BY created_at DESC, resource_id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(1) FROM health_resource_favorite
WHERE user_id = #{userId}

    AND resource_type = #{resourceType}

SELECT resource_id FROM health_resource_favorite
WHERE user_id = #{userId}

    AND resource_type = #{resourceType}

ORDER BY resource_id
